Translate the following GNU C++17 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

constexpr int MAXN = 55;
constexpr int MAXT = 2 * MAXN;
constexpr int MAXP = MAXT * MAXN;
constexpr int MAXE = 5 * MAXT * MAXN * MAXN;
constexpr int INF = 1000000000;

struct Edge {
    int to, rev, cap, cost;
};

vector<Edge> edges;
vector<int> adj[MAXP];

int n, m, k, c, d;
int people[MAXN];
int id[MAXN][MAXT];
int src = 1, sink = 2, nodeCnt = 2;
bool used[MAXP];
int dist[MAXP];
int answer;

void addEdge(int u, int v, int cost, int cap) {
    int fwd = (int)edges.size();
    edges.push_back({v, fwd + 1, cap, cost});
    edges.push_back({u, fwd, 0, -cost});
    adj[u].push_back(fwd);
    adj[v].push_back(fwd + 1);
}

bool spfa() {
    for (int i = 1; i <= nodeCnt; ++i) {
        used[i] = false;
        dist[i] = INF;
    }
    queue<int> q;
    dist[src] = 0;
    q.push(src);
    used[src] = true;
    while (!q.empty()) {
        int x = q.front();
        q.pop();
        used[x] = false;
        for (int idx : adj[x]) {
            const Edge &e = edges[idx];
            if (e.cap <= 0) continue;
            int y = e.to;
            if (dist[y] > dist[x] + e.cost) {
                dist[y] = dist[x] + e.cost;
                if (!used[y]) {
                    q.push(y);
                    used[y] = true;
                }
            }
        }
    }
    return dist[sink] < INF;
}

int augment(int x, int flow) {
    if (x == src) return flow;
    used[x] = true;
    int pushed = 0;
    for (int idx : adj[x]) {
        Edge &e = edges[idx];
        Edge &rev = edges[e.rev];
        int y = e.to;
        if (used[y] || rev.cap <= 0 || dist[x] < dist[y] + rev.cost) continue;
        int got = augment(y, min(flow - pushed, rev.cap));
        if (got) {
            rev.cap -= got;
            e.cap += got;
            pushed += got;
            if (pushed == flow) break;
        }
    }
    return pushed;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    edges.reserve(MAXE);

    cin >> n >> m >> k >> c >> d;
    for (int i = 1; i <= k; ++i) {
        int x;
        cin >> x;
        ++people[x];
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= k + m + 2; ++j) {
            id[i][j] = ++nodeCnt;
            if (i == 1) addEdge(id[i][j], sink, c * (j - 1), INF);
            if (j > 1) addEdge(id[i][j - 1], id[i][j], 0, INF);
        }
        if (people[i]) addEdge(src, id[i][1], 0, people[i]);
    }
    for (int i = 1; i <= m; ++i) {
        int a, b;
        cin >> a >> b;
        for (int j = 1; j <= k + m + 1; ++j) {
            for (int cost = 1; cost <= 2 * k - 1; cost += 2) {
                addEdge(id[a][j], id[b][j + 1], cost * d, 1);
                addEdge(id[b][j], id[a][j + 1], cost * d, 1);
            }
        }
    }

    for (int i = 1; i <= nodeCnt; ++i) reverse(adj[i].begin(), adj[i].end());

    int sent = 0;
    while (spfa()) {
        int add = -1;
        while (add) {
            memset(used, 0, sizeof(used));
            add = augment(sink, INF);
            sent += add;
            answer += dist[sink] * add;
        }
    }
    assert(sent == k);
    cout << answer << '\n';
    return 0;
}
